import math
import random

import pytest

from db import amp_to_db, power_to_db, db_to_amp, spl_from_pressure, add_incoherent_spl


def test_amp_ratio_2():
    assert amp_to_db(2) == pytest.approx(6.0206, abs=1e-4)


def test_power_ratio_1000():
    assert power_to_db(1000) == pytest.approx(30.0, abs=0.0)


def test_two_incoherent_60db():
    assert add_incoherent_spl(60, 60) == pytest.approx(63.0103, abs=1e-4)


def test_ten_equal_sources_add_10db():
    assert add_incoherent_spl(*([60.0] * 10)) == pytest.approx(70.0, abs=1e-9)


def test_spl_from_pressure():
    assert spl_from_pressure(0.2) == pytest.approx(80.0, abs=1e-9)


def test_round_trip():
    random.seed(1234)
    for _ in range(1000):
        x = random.uniform(1e-6, 1e6)
        assert db_to_amp(amp_to_db(x)) == pytest.approx(x, rel=1e-12)


def test_negative_pressure_raises():
    with pytest.raises(ValueError):
        spl_from_pressure(-1e-4)

