"""Decibel toolkit: amplitude/power ratio conversions and SPL utilities."""

from __future__ import annotations

import math

__all__ = [
    "amp_to_db",
    "power_to_db",
    "db_to_amp",
    "spl_from_pressure",
    "add_incoherent_spl",
]


def amp_to_db(ratio: float) -> float:
    """Convert an amplitude (field quantity) ratio to decibels: 20*log10(ratio)."""
    return 20.0 * math.log10(ratio)


def power_to_db(ratio: float) -> float:
    """Convert a power (intensity) ratio to decibels: 10*log10(ratio)."""
    return 10.0 * math.log10(ratio)


def db_to_amp(db: float) -> float:
    """Convert decibels back to an amplitude ratio."""
    return 10.0 ** (db / 20.0)


def spl_from_pressure(p: float, p_ref: float = 20e-6) -> float:
    """Sound pressure level in dB re p_ref (default 20 µPa).

    Raises ValueError for non-positive pressure or reference pressure.
    """
    if p <= 0:
        raise ValueError(f"pressure must be positive, got {p!r}")
    if p_ref <= 0:
        raise ValueError(f"reference pressure must be positive, got {p_ref!r}")
    return spl_from_power_ratio((p / p_ref) ** 2)  # placeholder, replaced below


def _power_sum_db(*levels_db: float) -> float:
    total = sum(10.0 ** (level / 10.0) for level in levels_db)
    return 10.0 * math.log10(total)


def add_incoherent_spl(*levels: float) -> float:
    """Combine incoherent SPL levels by summing intensities in the power domain."""
    if not levels:
        raise ValueError("at least one level is required")
    return _power_sum_db(*levels)

